// Blind reverse layer: width-13 plaintext transposition, then physical F-hold cycle.
#define REVERSE_LIBRARY
#include "reverse.cpp"
struct RS {Key key{};Order order{};array<V,W> path;int score=BAD;};
struct RJ {
 const LM&m;int lc,pen;array<Tape,W> cols;mt19937 rng;
 RJ(const Tape&c,int l,const LM&lm,int p):m(lm),lc(l),pen(p),rng(33017713+3301*l){auto a=columns(c,l);for(int j=0;j<W;j++)cols[j]=sub(a[j],1,38);}
 int score(const RS&s)const{int z=unary(s.path[s.order[0]],m,pen);for(int i=1;i<W;i++)z+=pairScore(s.path[s.order[i-1]],s.path[s.order[i]],m,pen);return z;}
 void recalc(RS&s){for(int j=0;j<W;j++){V&v=s.path[j];v.p.resize(R);int ph=v.start;for(int r=0;r<R;r++){if(v.mask&(1ULL<<r)){assert(cols[j][r]==0);v.p[r]=0;}else{int y=mod(cols[j][r]-s.key[ph],A);v.p[r]=y?y:29;ph=(ph+1)%Q;}}v.end=ph;}}
 // Exact unigram E-step: each physical column has independent start and legal hold mask, illegal consume soft only.
 int fitUnary(RS&s){int sc=0;for(int j=0;j<W;j++){array<int,Q>d,n;d.fill(0);array<array<int,Q>,R>back{};for(int r=0;r<R;r++){n.fill(BAD);int x=cols[j][r];for(int ph=0;ph<Q;ph++){auto put=[&](int np,int val){int v=d[ph]+val;if(v>n[np]){n[np]=v;back[r][np]=ph;}};int y=mod(x-s.key[ph],A);put((ph+1)%Q,m.u[y]-(y?0:pen));if(!x)put(ph,m.u[0]);}d=n;}int ph=max_element(d.begin(),d.end())-d.begin();V&v=s.path[j];v.end=ph;v.mask=0;for(int r=R-1;r>=0;r--){int p=back[r][ph];if(p==ph)v.mask|=1ULL<<r;ph=p;}v.start=ph;sc+=*max_element(d.begin(),d.end());}recalc(s);return sc;}
 int keyUnary(RS&s){int h[Q][A]={};for(int j=0;j<W;j++){auto&v=s.path[j];int ph=v.start;for(int r=0;r<R;r++)if(!(v.mask&(1ULL<<r))){h[ph][cols[j][r]]++;ph=(ph+1)%Q;}}for(int ph=0;ph<Q;ph++){int best=BAD,bk=s.key[ph];for(int k=0;k<A;k++){int v=0;for(int x=0;x<A;x++){int y=mod(x-k,A);v+=h[ph][x]*(m.u[y]-(y?0:pen));}if(v>best){best=v;bk=k;}}s.key[ph]=bk;}recalc(s);int total=0;for(auto&v:s.path)total+=unary(v,m,pen);return total;}
 void init(RS&s,int steps){int last=BAD;for(int i=0;i<steps;i++){int v=fitUnary(s);assert(v>=last);int k=keyUnary(s);assert(k>=v);if(k==last)break;last=k;}}
 int orderDP(RS&s){array<array<int,W>,W>e{};for(int a=0;a<W;a++)for(int b=0;b<W;b++)if(a!=b)e[a][b]=pairScore(s.path[a],s.path[b],m,pen);vector<int>d((ALL+1)*W,BAD);vector<int8_t>back(d.size(),-1);int first=1<<lc;d[first*W+lc]=unary(s.path[lc],m,pen);for(int mask=first;mask<ALL;mask++)if(mask&first)for(unsigned a=mask;a;a&=a-1){int j=__builtin_ctz(a),v=d[mask*W+j];if(v==BAD)continue;for(unsigned b=ALL^mask;b;b&=b-1){int k=__builtin_ctz(b),ix=(mask|(1<<k))*W+k,sc=v+e[j][k];if(sc>d[ix]){d[ix]=sc;back[ix]=j;}}}int last=max_element(d.begin()+ALL*W,d.end())-(d.begin()+ALL*W),mask=ALL,best=d[ALL*W+last];for(int i=W-1;i>=0;i--){s.order[i]=last;int p=back[mask*W+last];mask^=1<<last;last=p;}assert(s.order[0]==lc&&score(s)==best);return best;}
 int pathDP(RS&s){array<vector<V>,W>vs;for(int j=0;j<W;j++)vs[j]=variants(cols[j],s.key,-1,pen);auto f=exactChain(vs,s.order,m,pen);for(int j=0;j<W;j++)s.path[s.order[j]]=move(f.paths[j]);assert(score(s)==f.score);return f.score;}
 // Exact single-site updates on the general phase graph; pair potentials aggregated by phase and ciphertext pair.
 int keyGraph(RS&s){
  array<array<int,R>,W>phase;for(int j=0;j<W;j++){int ph=s.path[j].start;for(int r=0;r<R;r++)if(s.path[j].mask&(1ULL<<r))phase[j][r]=-1;else{phase[j][r]=ph;ph=(ph+1)%Q;}}
  int u[Q][A]={};vector<int>e((size_t)Q*Q*A*A);auto at=[&](int a,int b,int x,int y)->int&{return e[(((size_t)a*Q+b)*A+x)*A+y];};int constant=0;
  for(int r=0;r<R;r++)for(int j=0;j<W;j++){int col=s.order[j],p=phase[col][r],c=cols[col][r];if(p>=0)u[p][c]-=pen;if(!j){if(p<0)constant+=m.u[0];else for(int k=0;k<A;k++)u[p][k]+=m.u[mod(c-k,A)];continue;}int prev=s.order[j-1],a=phase[prev][r],x=cols[prev][r];if(a<0&&p<0)constant+=m.b[0][0];else if(a<0){for(int k=0;k<A;k++)u[p][k]+=m.b[0][mod(c-k,A)];}else if(p<0){for(int k=0;k<A;k++)u[a][k]+=m.b[mod(x-k,A)][0];}else if(a==p){for(int k=0;k<A;k++)u[p][k]+=m.b[mod(x-k,A)][mod(c-k,A)];}else{for(int k=0;k<A;k++)for(int l=0;l<A;l++){int val=m.b[mod(x-k,A)][mod(c-l,A)];at(a,p,k,l)+=val;at(p,a,l,k)+=val;}}}
  auto energy=[&](){int v=constant;for(int i=0;i<Q;i++){v+=u[i][s.key[i]];for(int j=i+1;j<Q;j++)v+=at(i,j,s.key[i],s.key[j]);}return v;};int before=score(s);assert(energy()==before);array<int,Q>seq;iota(seq.begin(),seq.end(),0);
  for(int sweep=0;sweep<12;sweep++){shuffle(seq.begin(),seq.end(),rng);bool changed=false;for(int i:seq){int best=BAD,bk=s.key[i];for(int k=0;k<A;k++){int v=u[i][k];for(int j=0;j<Q;j++)if(j!=i)v+=at(i,j,k,s.key[j]);if(v>best){best=v;bk=k;}}if(bk!=s.key[i]){changed=true;s.key[i]=bk;}}if(!changed)break;}
  // Coupled pair updates escape weak single-site minima. One exact sweep over phase pairs.
  for(int i=0;i<Q;i++)for(int j=i+1;j<Q;j++){int a[A],b[A];for(int k=0;k<A;k++){a[k]=u[i][k];b[k]=u[j][k];for(int t=0;t<Q;t++)if(t!=i&&t!=j){a[k]+=at(i,t,k,s.key[t]);b[k]+=at(j,t,k,s.key[t]);}}int best=a[s.key[i]]+b[s.key[j]]+at(i,j,s.key[i],s.key[j]),bi=s.key[i],bj=s.key[j];for(int k=0;k<A;k++)for(int l=0;l<A;l++){int v=a[k]+b[l]+at(i,j,k,l);if(v>best){best=v;bi=k;bj=l;}}s.key[i]=bi;s.key[j]=bj;}
  recalc(s);int after=score(s);assert(after==energy()&&after>=before);return after;
 }
 RS optimize(RS s,int cycles){int last=orderDP(s);for(int i=0;i<cycles;i++){int p=pathDP(s);assert(p>=last);int k=keyGraph(s);assert(k>=p);int o=orderDP(s);assert(o>=k);if(o==last){last=o;break;}last=o;}s.score=last;return s;}
 Key randomKey(){Key k;for(int&x:k)x=rng()%A;return k;}
 Key canon(Key k){Key b=k;for(int i=1;i<Q;i++){rotate(k.begin(),k.begin()+1,k.end());b=min(b,k);}return b;}
};
struct Candidate{Key k;int uni;RS s;};
int main(int argc,char**argv){if(argc!=6){cerr<<"usage: reverse_joint tapes.txt control1|control2|original split unigram_starts joint_starts\n";return 1;}auto src=load(argv[1]);string mode=argv[2];int lc=stoi(argv[3]),ustarts=stoi(argv[4]),jstarts=stoi(argv[5]);CCase a;if(mode=="original"){a.c=src[0].t;a.lm=model(src,"");}else a=make(src,mode);RJ j(a.c,lc,a.lm,6*SCALE);vector<Candidate>pool;auto start=chrono::steady_clock::now();for(int i=0;i<ustarts;i++){RS s;s.key=j.randomKey();j.init(s,25);int sc=0;for(auto&v:s.path)sc+=unary(v,a.lm,j.pen);Key k=j.canon(s.key);if(any_of(pool.begin(),pool.end(),[&](auto&v){return v.k==k;}))continue;pool.push_back({k,sc,s});sort(pool.begin(),pool.end(),[](auto&a,auto&b){return a.uni>b.uni;});if(pool.size()>64)pool.pop_back();}cout<<"UNI top "<<pool[0].uni<<" key "<<ordstr(pool[0].s.key)<<"\n"<<flush;
 vector<RS>elite;int best=BAD;for(int t=0;t<jstarts;t++){RS s;if(t<(int)pool.size())s=pool[t].s;else if(t%3==0||elite.empty()){s.key=j.randomKey();j.init(s,20);}else{s=elite[j.rng()%elite.size()];for(int i=0;i<1+(int)(j.rng()%3);i++)s.key[j.rng()%Q]=j.rng()%A;j.fitUnary(s);}s=j.optimize(s,15);if(s.score>best){best=s.score;cout<<"IMPROVE "<<mode<<" split "<<lc<<" restart "<<t<<" score "<<best<<" order "<<ordstr(s.order)<<" key "<<ordstr(s.key)<<"\n"<<flush;}Key k=j.canon(s.key);if(any_of(elite.begin(),elite.end(),[&](auto&v){return j.canon(v.key)==k&&v.order==s.order;}))continue;elite.push_back(s);sort(elite.begin(),elite.end(),[](auto&a,auto&b){return a.score>b.score;});if(elite.size()>16)elite.pop_back();}
 Fit bf;Key bk{};vector<Key>done;for(auto&s:elite){Key k=j.canon(s.key);if(find(done.begin(),done.end(),k)!=done.end())continue;done.push_back(k);auto f=trainFit(a.c,k,a.lm,lc);if(f.score>bf.score){bf=move(f);bk=k;}}
 if(bf.score==BAD){cout<<"NO_LEGAL "<<mode<<" split "<<lc<<" soft "<<best<<"\n";return 0;}Order o=orderOf(bf);auto ho=holdFit(a.c,bk,a.lm,bf);auto global=globalFit(a.c,bk,o,a.lm);cout<<"LEGAL_WIN "<<mode<<" split "<<lc<<" score "<<bf.score<<" order "<<ordstr(o)<<" key "<<ordstr(bk)<<" holdout "<<ho.score<<" globalPaths "<<global.paths<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";cout<<"TRAIN "<<enc(rowTape(bf))<<"\nHELD_BRIDGE "<<enc(rowTape(ho))<<"\nFULL "<<enc(global.p)<<"\n";if(a.planted){bool kr=false;for(int k=0;k<Q;k++){bool eq=true;for(int i=0;i<Q;i++)eq&=a.k[(k+i)%Q]==bk[i];kr|=eq;}cout<<"PLANT order "<<(o==a.o)<<" key_rotation "<<kr<<" train_exact "<<same(rowTape(bf),sub(a.p,W,38*W))<<" held_exact "<<(ho.score==BAD?-1:same(sub(rowTape(ho),W,17*W),sub(a.p,39*W,55*W)))<<" global_exact "<<same(global.p,a.p)<<" true_order "<<ordstr(a.o)<<" true_key "<<ordstr(a.k)<<"\n";}}
